from functools import lru_cache

def count_good_strings(n: int, k: int, s: str) -> int:
    MOD = 998244353

    def is_palindrome(sub: str) -> bool:
        return sub == sub[::-1]

    @lru_cache(maxsize=None)
    def dfs(index: int, prev: str) -> int:
        if index == n:
            return 1
        if s[index] != '?':
            return dfs(index + 1, s[index])
        total = 0
        for choice in 'AB':
            new_prev = prev + choice
            if len(new_prev) >= k and is_palindrome(new_prev[-k:]):
                continue
            total += dfs(index + 1, new_prev)
        return total % MOD

    return dfs(0, '')

