from typing import List
import math

def manhattan_distance(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def min_moves(kx, ky, px, py):
    # Calculate the minimum moves to reach (px, py) from (kx, ky)
    return max(abs(px - kx), abs(py - ky)) // 3 + (abs(px - kx) % 3 != 0 or abs(py - ky) % 3 != 0)

def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    n = len(positions)
    dp = [math.inf] * n
    for i in range(n):
        dp[i] = min_moves(kx, ky, positions[i][0], positions[i][1])

    for _ in range(n - 1):
        new_dp = [math.inf] * n
        for i in range(n):
            for j in range(n):
                if i != j:
                    new_dp[j] = min(new_dp[j], dp[i] + min_moves(positions[i][0], positions[i][1], positions[j][0], positions[j][1]))
        dp = new_dp[:]

    return sum(dp)
