from typing import List
import heapq

def manhattan_distance(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

def min_moves_to_capture(knight_pos, pawn_pos):
    visited = set()
    queue = [(0, knight_pos)]
    while queue:
        moves, pos = heapq.heappop(queue)
        if pos in visited:
            continue
        visited.add(pos)
        if manhattan_distance(pos, pawn_pos) <= 3:
            return moves + 1
        for dx, dy in [(-2, -1), (-2, 1), (2, -1), (2, 1), (-1, -2), (-1, 2), (1, -2), (1, 2)]:
            next_pos = (pos[0] + dx, pos[1] + dy)
            if 0 <= next_pos[0] < 50 and 0 <= next_pos[1] < 50:
                heapq.heappush(queue, (moves + 1, next_pos))
    return float('inf')

def max_knight_moves(kx: int, ky: int, positions: List[List[int]]) -> int:
    knight_pos = (kx, ky)
    total_moves = 0
    while positions:
        min_moves = float('inf')
        best_pawn = None
        for pawn_pos in positions:
            moves = min_moves_to_capture(knight_pos, tuple(pawn_pos))
            if moves < min_moves:
                min_moves = moves
                best_pawn = pawn_pos
        total_moves += min_moves
        positions.remove(best_pawn)
        knight_pos = tuple(best_pawn)
    return total_moves

